Here’s a minimal **Flask session login** using Flask-Login and Werkzeug password hashing. It stores a password hash at registration and checks that stored hash at login—**never create a new hash from the submitted password during login**, since password hashes use salts.

Install the dependencies:

```bash
pip install Flask Flask-SQLAlchemy Flask-Login
```

```python
import os

from flask import Flask, flash, redirect, render_template_string, request, url_for
from flask_login import (
    LoginManager, UserMixin, current_user, login_required,
    login_user, logout_user,
)
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import check_password_hash, generate_password_hash

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ["SECRET_KEY"],  # Set a long, random secret in your environment
    SQLALCHEMY_DATABASE_URI="sqlite:///app.db",
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    SESSION_COOKIE_SECURE=True,  # Use HTTPS in production
)

db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = "login"


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)


@login_manager.user_loader
def load_user(user_id):
    # Flask-Login passes the user ID stored in the session.
    try:
        return db.session.get(User, int(user_id))
    except (TypeError, ValueError):
        return None


@app.route("/register", methods=["GET", "POST"])
def register():
    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        if not username or not password:
            flash("Username and password are required.")
        elif len(password) < 12:
            flash("Use a password of at least 12 characters.")
        elif User.query.filter_by(username=username).first():
            flash("That username is already taken.")
        else:
            user = User(
                username=username,
                password_hash=generate_password_hash(password),
            )
            db.session.add(user)
            db.session.commit()
            flash("Account created. You can now log in.")
            return redirect(url_for("login"))

    return render_template_string(FORM, heading="Register", endpoint="register")


@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")
        user = User.query.filter_by(username=username).first()

        if user and check_password_hash(user.password_hash, password):
            login_user(user)
            return redirect(url_for("account"))

        flash("Invalid username or password.")

    return render_template_string(FORM, heading="Log in", endpoint="login")


@app.route("/account")
@login_required
def account():
    return f"Welcome, {current_user.username}!"


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))


FORM = """
<h1>{{ heading }}</h1>
{% with messages = get_flashed_messages() %}
  {% for message in messages %}<p>{{ message }}</p>{% endfor %}
{% endwith %}
<form method="post" action="{{ url_for(endpoint) }}">
  <label>Username <input name="username" required></label><br>
  <label>Password <input name="password" type="password" required></label><br>
  <button type="submit">{{ heading }}</button>
</form>
"""


if __name__ == "__main__":
    with app.app_context():
        db.create_all()
    app.run()
```

Set `SECRET_KEY` before starting the app, for example:

```bash
export SECRET_KEY="$(python -c 'import secrets; print(secrets.token_hex(32))')"
```

For production, use HTTPS and add CSRF protection to the forms (for example, with Flask-WTF). Don’t expose Flask’s development server publicly.

Below is a basic **Flask-Login** setup using a database-backed user record and Werkzeug password hashing. It keeps each user’s password hash in the database—never generate a fresh hash during login.

Install the dependencies:

```bash
pip install Flask Flask-Login Flask-SQLAlchemy
```

```python
import os

from flask import Flask, flash, redirect, render_template, request, url_for
from flask_login import (
    LoginManager,
    UserMixin,
    current_user,
    login_required,
    login_user,
    logout_user,
)
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import check_password_hash, generate_password_hash

app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ["FLASK_SECRET_KEY"]  # Set a long, random value
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///budget_tracker.db"
app.config["SQLALCHEMY_TRACK_MODIFICATIONS"] = False

db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = "login"


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)

    def set_password(self, password):
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)


@login_manager.user_loader
def load_user(user_id):
    # Flask-Login stores the ID in the session; reload the user from the database.
    return db.session.get(User, int(user_id))


@app.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        if not username or not password:
            flash("Enter your username and password.", "error")
            return render_template("login.html"), 400

        user = db.session.execute(
            db.select(User).where(User.username == username)
        ).scalar_one_or_none()

        if user is None or not user.check_password(password):
            # Use the same message for either failure to avoid revealing usernames.
            flash("Invalid username or password.", "error")
            return render_template("login.html"), 401

        login_user(user)
        return redirect(url_for("dashboard"))

    return render_template("login.html")


@app.route("/dashboard")
@login_required
def dashboard():
    return f"Welcome, {current_user.username}!"


@app.route("/logout", methods=["POST"])
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))
```

Create `templates/login.html`:

```html
<form method="post">
  <label for="username">Username</label>
  <input id="username" name="username" autocomplete="username" required>

  <label for="password">Password</label>
  <input id="password" name="password" type="password"
         autocomplete="current-password" required>

  <button type="submit">Log in</button>
</form>

{% for category, message in get_flashed_messages(with_categories=true) %}
  <p class="{{ category }}">{{ message }}</p>
{% endfor %}
```

When registering a user, hash the password before saving:

```python
user = User(username=username)
user.set_password(password)
db.session.add(user)
db.session.commit()
```

For production, set `FLASK_SECRET_KEY` to a securely generated secret, serve the app over HTTPS, enable secure session-cookie settings, and protect login/logout forms against CSRF. If you already have a `User` model and database, adapt the example to those rather than creating a second user table.

